#!/usr/bin/env bash
# dev-stop.sh (generated by engineering-platform runtime-recipe asset)
# Graceful stop of backend/frontend started by THIS recipe (dev-start.sh).
# PID-driven + process-group kill: only processes recorded in .runtime/*.pid
# are stopped — never unrelated user processes. State files are cleaned.
set -eo pipefail

ROOT_DIR="$(cd "$(dirname "$BASH_SOURCE[0]")/.." && pwd)"
RUNTIME_DIR="$ROOT_DIR/.runtime"

log() { echo "[dev-stop] $*"; }

stop_pid_file() {
  local pid_file="$1"
  local name="$2"
  if [[ ! -f "$pid_file" ]]; then
    log "$name: not running (no pid file)"
    return 0
  fi
  local pid
  pid="$(cat "$pid_file")"
  if ! kill -0 "$pid" 2>/dev/null; then
    log "$name: pid $pid not alive — removing stale pid file"
    rm -f "$pid_file"
    return 0
  fi
  log "$name: stopping process group $pid (SIGTERM)..."
  # process group kill: dev-start launches with setsid, so -pid targets the
  # whole group (java, or pnpm+vite children) without touching other processes
  kill -- -"$pid" 2>/dev/null || kill "$pid" 2>/dev/null || true
  local attempts=0
  while kill -0 "$pid" 2>/dev/null && [[ $attempts -lt 15 ]]; do
    sleep 1
    attempts=$((attempts + 1))
  done
  if kill -0 "$pid" 2>/dev/null; then
    log "$name: graceful timeout — sending SIGKILL to group"
    kill -9 -- -"$pid" 2>/dev/null || kill -9 "$pid" 2>/dev/null || true
    sleep 1
  fi
  rm -f "$pid_file"
  log "$name: stopped (pid $pid)"
}

stop_pid_file "$RUNTIME_DIR/backend.pid" "backend"
stop_pid_file "$RUNTIME_DIR/frontend.pid" "frontend"

# clean machine-readable state (ports/urls) after stop
rm -f "$RUNTIME_DIR/backend.port" "$RUNTIME_DIR/backend.url"
rm -f "$RUNTIME_DIR/frontend.port" "$RUNTIME_DIR/frontend.url"
log "done."
